let matchedAnswer = null;
for (const item of faqDatabase) {
  if (item.keywords.some(kw => userMessage.includes(kw))) {
    matchedAnswer = item.answer;
    break;
  }
}

if (matchedAnswer) {
  return [{ 
    json: { 
      isFaqMatch: Boolean(true), 
      reply: matchedAnswer, 
      sessionId: inputData.body && inputData.body.sessionId ? inputData.body.sessionId : 'default-session' 
    } 
  }];
}

return [{ 
  json: { 
    isFaqMatch: Boolean(false), 
    originalInput: inputData 
  } 
}];

const inputData = $input.first().json;
if (typeof inputData === 'string') return JSON.stringify({ error: "Send JSON." });
const action = inputData.action || 'search';
let table = inputData.table || 'properties';
let queryParams = inputData.queryParams || '';
let bodyData = inputData.body || null;
// NOTE: Set these via n8n environment variables / credentials rather than hardcoding.
const SUPABASE_URL = $env.SUPABASE_URL + '/rest/v1/';
const SUPABASE_KEY = $env.SUPABASE_SERVICE_ROLE_KEY;
let url = SUPABASE_URL + table;
let method = 'GET';
if (action === 'search') {
  method = 'GET';
  if (queryParams) url += '?' + encodeURI(queryParams);
} else if (action === 'insert') {
  method = 'POST';
}
let options = {
  method: method,
  url: url,
  headers: { 'apikey': SUPABASE_KEY, 'Authorization': 'Bearer ' + SUPABASE_KEY, 'Content-Type': 'application/json', 'Prefer': 'return=representation' },
  json: true
};
if (method === 'POST' && bodyData) options.body = bodyData;
try {
  const data = await this.helpers.httpRequest(options);
  return JSON.stringify({ success: true, data: data });
} catch (error) {
  return JSON.stringify({ success: false, error: error.message });
}

const inputData = $input.first().json;

let userMessage = '';
if (inputData.body) {
  if (typeof inputData.body.message === 'string') {
    userMessage = inputData.body.message;
  } else if (typeof inputData.body.text === 'string') {
    userMessage = inputData.body.text;
  } else if (inputData.body.arguments && typeof inputData.body.arguments.message === 'string') {
    userMessage = inputData.body.arguments.message;
  } else if (typeof inputData.body.query === 'string') {
    userMessage = inputData.body.query;
  }
}
userMessage = userMessage.toLowerCase().trim();

const faqDatabase = [
  {
    keywords: ['hours', 'timing', 'open', 'time', 'working hours', 'schedule'],
    answer: "Diamond Real Estate is open Monday through Saturday from 9:00 AM to 7:00 PM Pakistan Standard Time."
  },
  {
    keywords: ['location', 'address', 'where', 'office', 'headquarters', 'map'],
    answer: "Our main corporate office is located in Lahore, Pakistan, serving premium commercial and residential properties."
  },
  {
    keywords: ['contact', 'phone', 'support', 'call', 'email', 'reach out'],
    answer: "You can reach our team via email or through our online booking forms."
  },
  {
    keywords: ['hello', 'hi', 'hey', 'start', 'greetings'],
    answer: "Hello! Welcome to Diamond Real Estate. How can I assist you with your property search today?"
  },
  {
    keywords: ['about', 'who are you', 'company', 'diamond real estate'],
    answer: "Diamond Real Estate is a premier technology-driven property advisory firm specializing in residential and commercial investments."
  },
  {
    keywords: ['book', 'meeting', 'visit', 'schedule', 'viewing', 'appointment'],
    answer: "You can schedule a property viewing by providing your name, phone number, and national ID card details to our team."
  }
];

let matchedAnswer = null;
for (const item of faqDatabase) {
  if (item.keywords.some(kw => userMessage.includes(kw))) {
    matchedAnswer = item.answer;
    break;
  }
}

if (matchedAnswer) {
  return [{
    json: {
      route: "faq",
      output: matchedAnswer
    }
  }];
}

return [{
  json: {
    route: "supabase",
    userMessage: userMessage
  }
}];

const properties = $input.all().map(item => item.json);
const rawQuery = $('Voice RAG & Router1').first().json.userMessage || '';
const query = rawQuery.toLowerCase().trim();

// Split query into individual search keywords (e.g., "green", "valley") for flexible matching
const keywords = query.split(/\s+/).filter(word => word.length > 2);

const matched = properties.filter(p => {
  const title = (p.title || '').toLowerCase();
  const location = (p.location || '').toLowerCase();
  const type = (p.property_type || '').toLowerCase();

  // Check if any keyword matches title, location, or property type
  return keywords.some(kw => title.includes(kw) || location.includes(kw) || type.includes(kw)) ||
         title.includes(query) || location.includes(query);
});

let responseText = "";
if (matched.length > 0) {
  const topProp = matched[0];
  responseText = `I found ${topProp.title} located in ${topProp.location}, priced at ${topProp.price}. Would you like to schedule a viewing?`;
} else {
  responseText = `I checked our listings for "${rawQuery}", but couldn't find an exact match. However, we have several other residential and commercial properties available. Would you like to hear about them?`;
}

return [{ json: { output: responseText } }];
